checks.excerpt:
timer0_start();
while(ECHO==0) {
    if(TF0!=0) { TR0=0; return 0; }
}
timer0_start();
while(ECHO!=0) {
    if(TF0!=0) { TR0=0; return 0; }
}
TR0=0;
if(TF0!=0) return 0;
ticks=((unsigned int)TH0<<8)|TL0;
return ticks;

if(raw != key_candidate) {
    key_candidate = raw;
    key_samples = 1;
} else if(key_samples < 3) {
    key_samples++;
}
if(key_samples < 3 || raw == key_stable)
    return;
key_stable = raw;
if(raw == 0) {
    key_armed = 1; return;
}
if(!key_armed) return;
key_armed = 0;

quarter_count++;
if(quarter_count >= 4) {
    quarter_count = 0;
    if(alarm_on) {
        if(phase_ms != 0) phase_ms--;
        if(phase_ms == 0) {
            burst_on = !burst_on;
            phase_ms = burst_on ?
                50 : quiet_ms;
        }
    }
}
if(alarm_on && burst_on) BEEP = !BEEP;
else BEEP = 1;
